    "description": "中际旭创7月28日在电话会议上表示，目前几乎所有客户订单已覆盖2026年全年，部分客户订单已下到2027年，交付计划细化到月度。2027年行业情况明晰，800G、1.6T、2.4T、NPO等产品需求都具有较强的确定性，增速也非常快。部分重点客户已给出2028年新产品指引，指引金额非常可观。因为公司预计下游重点客户的资本开支仍具有很强的可持续性，客户愿意继续加大行业投入。（证券时报）",
