    "content": "新华社旧金山7月28日电（记者吴晓凌）美国波音公司28日发布财报显示，该公司今年第二季度净亏损4.28亿美元，较去年同期净亏损6.12亿美元进一步收窄。 财报显示，受益于民用飞机交付量增加，波音第二季度营业收入为245.6亿美元，同比增长8%。当季共交付171架民用飞机，高于去年同期的150架。 波音第二季度经营现金流为13.64亿美元，自由现金流为6.31亿美元，期末订单储备增至创纪录的7150亿美元，其中包括超过6200架民用飞机订单。 波音公司总裁兼首席执行官凯利·奥特伯格表示，公司将继续聚焦安全、质量和准时…"
