    "author": "潘若曦/检察日报",
    "description": "航班超售的本质，是航空公司为提升运营效率所做的商业选择，但这份选择的成本，不该由不知情的旅客来承担。 每逢民航旺季，总有旅客因为航班超售被挡在登机口，最终延误行程。据调查，近七成旅客并不能够完整掌握航班超售规则，超七成旅客反映超售风险提示文字过小、位置隐蔽、辨识度低，只有不到三成旅客清晰知晓超售后全额退改签、食宿安置、经济补偿等相关权益。近日，京津冀三地消协组织就航班超售问题约谈10家航空公司及5家线上售票平台，要求其自查整改，于今年8…",
    "content": "航班超售的本质，是航空公司为提升运营效率所做的商业选择，但这份选择的成本，不该由不知情的旅客来承担。 每逢民航旺季，总有旅客因为航班超售被挡在登机口，最终延误行程。据调查，近七成旅客并不能够完整掌握航班超售规则，超七成旅客反映超售风险提示文字过小、位置隐蔽、辨识度低，只有不到三成旅客清晰知晓超售后全额退改签、食宿安置、经济补偿等相关权益。近日，京津冀三地消协组织就航班超售问题约谈10家航空公司及5家线上售票平台，要求其自查整改，于今年8月31日前整改完毕（据7月28日《人民日报》）。 旅客提前买了票、值了机、过了安…"
