    "description": "新华社纽约7月28日电 国际油价28日显著下跌。 截至当天收盘，纽约商品交易所9月交货的轻质原油期货价格下跌3.35美元，收于每桶79.26美元，跌幅为4.06%；9月交货的伦敦布伦特原油期货价格下跌4.27美元，收于每桶84.09美元，跌幅为4.83%。",
    "content": "新华社纽约7月28日电 国际油价28日显著下跌。 截至当天收盘，纽约商品交易所9月交货的轻质原油期货价格下跌3.35美元，收于每桶79.26美元，跌幅为4.06%；9月交货的伦敦布伦特原油期货价格下跌4.27美元，收于每桶84.09美元，跌幅为4.83%。"
