    "content": "新华社华盛顿7月28日电（记者黄强 徐剑梅）美国总统特朗普28日上午在白宫同到访的以色列总理内塔尼亚胡举行会谈。这是两人自美以2月底对伊朗联合发动大规模军事行动以来的首次面对面会晤。 据美国媒体报道，此次会晤持续了一个多小时，而特朗普此前刚同乌克兰总统泽连斯基进行了约一个小时的会谈。白宫新闻秘书莱维特在社交媒体发文称，两场会谈“都积极且富有成效”。 白宫尚未公布更多会谈内容。但据白宫此前发布的消息，除伊朗战事外，两人还将讨论有关以色列与阿拉伯国家关系正常化的“亚伯拉罕协议”以及美以和黎巴嫩先前达成的三方框架协议进展…"
