    "content": "当地时间7月28日，美国总统特朗普在白宫与到访的以色列总理内塔尼亚胡举行会晤。以色列方面消息称，整个会晤持续约一小时。白宫方面随后发表声明称，此次会谈具有“积极和富有建设性”的意义。 据以色列总理府高级官员透露，此次会晤氛围良好，两位领导人就多项地区议题进行探讨，其中伊朗核问题成为核心议题。美以双方在会后重申了“阻止伊朗获得核武器”的共同承诺，并就加强美以盟友关系、拓展中东地区合作机遇交换了意见。 本次会晤全程未举行两国领导人的单独会谈，所有高级阁僚均参与其中。美方出席人员包括副总统万斯、国务卿鲁比奥、国防部长赫格…"
