    "content": "中国本周传出已开始生产自主研发的浸没式深紫外光刻机，预计今年内交付约五台这类晶片制造关键设备。受访学者评估，若消息属实，意味着美国对华科技战持续数年的“小院高墙”策略宣告失效，中国应对美国以晶片和光刻机卡脖子取得里程碑式突破，但在设备质量追赶行业龙头可能有待数年。 美国科技媒体《信息报》（The Information）星期一（7月27日）引述两名消息人士披露，位于上海的一家国资企业开始生产深紫外光刻机（Deep Ultraviolet Lithography，简称DUV），并已从光刻初创公司上海宇量昇科技等其他中…"
