    "content": "新华社杭州7月28日电（记者冯源、段菁菁）今年年初热播的历史剧《太平年》让不少观众对五代十国的历史产生了浓厚兴趣，“太平年·天下同宁”大展28日在浙江省博物馆之江馆区开幕，以文物联动影视，让“太平年”从荧屏走进展厅。 “太平年·天下同宁”大展将持续至2027年6月20日，分三期，将一共展出来自全国近100家文博机构的近1000件文物。首期展出时间为今年7月28日至11月1日，以“吴越初兴”为主题，介绍了钱镠在晚唐藩镇割据中崛起，建立吴越国，以及吴越国三世五王奉行“保境安民”“善事中国”的政策，所取得的成就。后两期分…"
