    "description": "新华社广州7月28日电（记者胡拿云、王丰）记者28日从南方电网了解到，截至18时，受今年第12号台风“红霞”影响的广东用户已全部恢复供电。 26日凌晨，台风“红霞”的中心在广东省惠州市惠东县平海镇登陆，登陆时中心附近最大风力14级（45米/秒）。台风登陆时，部分电力设施遭台风损毁，不少居民家中出现断电情况。随后，电力部门组织抢险力量赴台风登陆点开展抢修工作。 据电力部门介绍，在台风袭击广东期间，惠州、汕尾等地50余万户用户用电受到影响。…",
    "content": "新华社广州7月28日电（记者胡拿云、王丰）记者28日从南方电网了解到，截至18时，受今年第12号台风“红霞”影响的广东用户已全部恢复供电。 26日凌晨，台风“红霞”的中心在广东省惠州市惠东县平海镇登陆，登陆时中心附近最大风力14级（45米/秒）。台风登陆时，部分电力设施遭台风损毁，不少居民家中出现断电情况。随后，电力部门组织抢险力量赴台风登陆点开展抢修工作。 据电力部门介绍，在台风袭击广东期间，惠州、汕尾等地50余万户用户用电受到影响。广东电网公司在其供电营业区组建了200余支抢险队伍，奋战60余小时，目前已全部恢…"
