    "content": "近日，顺章汽车集团有限公司通过官方微信公众号发布一则《辟谣声明》，称一名叫做“谢尚晋”的社会人士虚构“中国人民大学文艺复兴研究院副院长、教授、博士生导师”身份，与该公司展开合作，经核实这一头衔为捏造，遂解除与其合作关系。 顺章汽车微信公众号发布的声明&nbsp; 7月27日下午，澎湃新闻记者从中国人民大学艺术学院确认，中国人民大学并无名叫“谢尚晋”的教职人员。 7月27日晚，谢尚晋在接受澎湃新闻记者电话采访时承认“头衔使用存在不规范”，但他说“并不存在伪造身份的问题”。谢尚晋说，他2018年就开始跟中国人民大学文艺…"
