    "title": "我国将统筹推进革命文物环境整治工程",
    "link": "http://www.news.cn/20260728/787d08c0c7764aeb91c4f513218e4d63/c.html",
    "pub_date": "2026-07-28 22:08:57",
    "author": "徐壮",
    "description": "7月28日，国家文物局举行新闻发布会，介绍出台《革命文物保护工程技术导则（试行）》有关情况。技术导则明确，统筹推进革命文物环境整治工程，保护好有价值的历史环境要素，做到“守底线、做减法、慎加法”，确保革命圣地真实、朴素，有艰苦奋斗氛围、有浓厚历史感。 技术导则旨在规范指导革命文物保护技术行为，要求始终把保护放在首位，明确“保什么”和“怎么保”的基本要求。技术导则围绕调查与评估、勘察与设计、施工与验收三个关键阶段，强调研究性保护，构建“革…",
    "content": "7月28日，国家文物局举行新闻发布会，介绍出台《革命文物保护工程技术导则（试行）》有关情况。技术导则明确，统筹推进革命文物环境整治工程，保护好有价值的历史环境要素，做到“守底线、做减法、慎加法”，确保革命圣地真实、朴素，有艰苦奋斗氛围、有浓厚历史感。 技术导则旨在规范指导革命文物保护技术行为，要求始终把保护放在首位，明确“保什么”和“怎么保”的基本要求。技术导则围绕调查与评估、勘察与设计、施工与验收三个关键阶段，强调研究性保护，构建“革命史实—文物本体—历史环境—有价值历史痕迹”的关联体系；强调修缮设计的科学性，确…"
