    "content": "记者7月28日从国家文物局举行的新闻发布会上获悉，国家文物局将按照新出台的《国有文物资源数据管理办法》规定，建设国有文物资源数据登记管理平台，编制登记管理制度，统筹布局国家及区域存储中心，确保政策落地见效，充分释放国有文物资源数据要素价值。 近年来，社会各界对文物数据的需求日益增长。国家文物局科技教育司司长罗静介绍，《国有文物资源数据管理办法》明晰了国有文物资源数据权益主体，明确了国有文物资源数据责任主体，构建了数据采集、加工、存储、传输、登记、服务全生命周期管理制度，对实现文物数据权益清晰、开放有序、利用有效、安…"
