    "content": "与许多癌症不同，结直肠癌具有较长的癌变过程，被认为是少数具有明确癌前阶段、可以通过筛查提前干预的癌种之一，更高发于老年群体。 高油和低纤维素饮食，是肠癌发病率上升很重要的原因，另外还有久坐和肥胖。 南方周末记者 陈杨 责任编辑：黄思卓 2026年7月27日，据央视新闻消息，日本作家东野圭吾于当地时间7月23日因患结直肠癌去世，终年68岁。东野圭吾是日本极具影响力的畅销作家，他的离世，让结直肠癌进入更多人的视野。 结直肠癌，包括结肠癌和直肠癌，是我国恶性肿瘤中最常见的类型之一。国家癌症中心团队2026年发布的《202…"
