    "description": "中新网海口7月28日电(符宇群 王梓懿)28日在海口举行的一场海峡两岸(海南)青年厨艺展示交流赛上，香橙咖啡羊小排、糟粕醋水果鲜鱼片、黄皮烩海石斑等创意水果菜品轮番上桌，参赛台湾青年厨师灵感迸发、匠心独运，深挖热带水果入菜的烹饪可能性，将琼台饮食特色巧妙结合，全新口味让现场观众耳目一新。",
    "content": "中新网海口7月28日电(符宇群 王梓懿)28日在海口举行的一场海峡两岸(海南)青年厨艺展示交流赛上，香橙咖啡羊小排、糟粕醋水果鲜鱼片、黄皮烩海石斑等创意水果菜品轮番上桌，参赛台湾青年厨师灵感迸发、匠心独运，深挖热带水果入菜的烹饪可能性，将琼台饮食特色巧妙结合，全新口味让现场观众耳目一新。"
