    "content": "新华社北京7月28日电 题：做胸怀报国志的奋斗者，民营企业家这样干 新华社记者赵怡宁、范思翔 爱国情、报国志，是一代代中国企业家刻在骨子里的基因，是拼搏奋斗的重要动力源泉。 始终与国家发展同频共振、在关键领域勇挑重担、以长期主义筑牢根基……“十五五”开局之年，广大民营企业家牢记嘱托，满怀创业和报国激情，迎难而上锐意创新，专心致志做强做优做大企业，以实际行动坚定做中国特色社会主义的建设者、中国式现代化的促进者。 顺应发展潮流，在转型升级中开辟发展空间—— “魏桥创业集团40余年的发展历程，就是一部紧跟国家所需、攻坚产…"
