    "description": "新华社北京7月28日电（记者王悦阳）市场监管总局价监竞争局局长姚雷在28日召开的“市场化活动违法违规行为专项整治”专题新闻发布会上介绍，截至目前，全国市场监管部门共查办节庆展会论坛相关违法案件197件，罚没277.1万元，责令476家主体整改。 清理规范节庆、展会、论坛、榜单排行，是规范市场秩序、优化营商环境、维护群众权益的重要举措。 2026年3月以来，市场监管总局配合宣传、商务、文旅等活动主管部门，部署全国市场监管系统开展为期三个月…",
    "content": "新华社北京7月28日电（记者王悦阳）市场监管总局价监竞争局局长姚雷在28日召开的“市场化活动违法违规行为专项整治”专题新闻发布会上介绍，截至目前，全国市场监管部门共查办节庆展会论坛相关违法案件197件，罚没277.1万元，责令476家主体整改。 清理规范节庆、展会、论坛、榜单排行，是规范市场秩序、优化营商环境、维护群众权益的重要举措。 2026年3月以来，市场监管总局配合宣传、商务、文旅等活动主管部门，部署全国市场监管系统开展为期三个月的节庆展会论坛活动违法违规行为专项整治，依法查处节庆展会论坛活动中虚假宣传、强制…"
