    "content": "新华社北京/耶路撒冷7月28日电 题：微妙时刻访美，内塔尼亚胡有何诉求 新华社记者马倩 陈书林 王卓伦 当地时间27日，以色列总理内塔尼亚胡抵达美国首都华盛顿。他将与美国总统特朗普在白宫会晤。这是内塔尼亚胡自伊朗战事爆发以来首次访美。 分析人士认为，近期美以分歧日渐公开，内塔尼亚胡此访意在与美方重建信任并在对伊政策上加强协调。此外，内塔尼亚胡与特朗普接下来都面临关键选举考验，双方需要相互“借力”。尽管美以政策分歧频频见诸报端，但两国战略利益依然高度契合，同盟根基依旧稳固。 “修复之旅” 内塔尼亚胡此访是他在特朗普第…"
