    "content": "新华社巴格达7月28日电（记者李军）伊拉克石油部28日发表声明说，该国5月和6月共出口原油约3211万桶，月均出口量远低于中东战事爆发前水平。 声明援引伊拉克国家石油营销组织的统计数据说，5月和6月，伊拉克通过伊南部巴士拉出口原油约2024万桶，通过伊北部基尔库克经土耳其杰伊汉港出口原油约1031万桶，通过伊北部库尔德自治区经杰伊汉港出口原油约156万桶。 自2月28日中东战事爆发以来，全球能源贸易关键通道霍尔木兹海峡通航几近停滞，导致近几个月来伊拉克原油出口量大幅减少。数据显示，伊拉克2月原油出口量约为9987万…"
