    "content": "新华社北京7月28日电（记者戴小河）中国大唐28日宣布，大唐郓城630℃超超临界二次再热煤电机组当日全容量投运，这是世界首个再热蒸汽温度超过630℃、发电热效率突破50%的超超临界煤电项目，单台机组容量100万千瓦。 中国大唐董事长吕军表示，这一机组创造了同类型机组温度最高、压力最高、效率最高、供电煤耗最低的世界纪录，进一步提高燃煤效率，降低度电耗煤量。 吕军介绍，机组以技术革新、工艺升级、装备迭代、材料创新为抓手，实现“新技术、新工艺、新材料、新装备”突破与集成应用，设备国产化率达98.89%，成功突破发电热效率…"
