    "description": "7月上旬，纪念新华社与塔斯社合作70周年中俄跨境联合采访活动俄罗斯段顺利开展。联合采访团赴特维尔、雅罗斯拉夫尔、伊万诺沃、弗拉基米尔、普廖斯、穆罗姆等多座城市实地采访，近距离领略俄罗斯深厚的历史底蕴与独特的文化魅力。 采访团中多名塔斯社成员都有学习中文的经历，在他们眼中，中国是一个怎样的国度呢？ 记者：许杨 王超 周天翮 新华社音视频部制作",
    "content": "7月上旬，纪念新华社与塔斯社合作70周年中俄跨境联合采访活动俄罗斯段顺利开展。联合采访团赴特维尔、雅罗斯拉夫尔、伊万诺沃、弗拉基米尔、普廖斯、穆罗姆等多座城市实地采访，近距离领略俄罗斯深厚的历史底蕴与独特的文化魅力。 采访团中多名塔斯社成员都有学习中文的经历，在他们眼中，中国是一个怎样的国度呢？ 记者：许杨 王超 周天翮 新华社音视频部制作"
