    "content": "（北京/华盛顿综合讯）针对欧美批评中国输出过剩产能，中国政府发文反驳，强调保护主义将扰乱全球经贸秩序，为世界经济增长带来长期风险。 中国商务部官网星期二（7月28日）发布题为《关于所谓“产能过剩”问题的中方立场》的文件。 文件称，近年来，有关国家和经济体对自身产业竞争力、市场地位的担忧增多，将经贸问题政治化，指责中国产能冲击世界市场，并以此为借口不断加码对华限制措施，“保护主义加剧升温”。 文件梳理第一次工业革命以来全球产能格局的历史演变，指全球对“产能过剩”概念目前尚未形成广泛共识，提出应根据不同发展阶段、发展水…"
