    "content": "新华社北京7月28日电（记者田晨旭）随着盛夏来临，让人体感湿黏闷热的“桑拿模式”开启。28日14时，北京城区气温处在33摄氏度至35摄氏度之间，体感闷热。 7月28日，北京街景。新华社记者 田晨旭 摄 每到盛夏，北京常常会出现类似的“闷到喘不上气”的天气。这种天气常常不是高温天气，但浑身黏腻、出汗难蒸发，如同呆在汗蒸房里，也就是所谓的“桑拿天”。 为何会形成“桑拿天”？气象部门介绍，北京桑拿天的形成主要受三方面因素影响。 一是副热带高压的控制。下沉气流带来晴热高温，叠加偏南风输送的海洋水汽与微风甚至静风条件，易形成…"
