    "description": "近日，习近平总书记对侨务工作作出重要指示强调，更好凝聚侨心侨力，促进海内外中华儿女团结奋斗。 侨务工作是党和国家一项长期性、战略性工作，始终与国家经济社会发展、对外友好交流合作紧密相连，始终与时代发展脉搏同频共振。党的十八大以来，习近平总书记始终高度重视侨务工作，在不同场合作出一系列重要论述。一起学习领会。 文案：姜子炜 屈彦 曹力 设计：潘红宇 新华社新媒体中心制作 新华社出品",
