    "content": "新华社比什凯克7月28日电（记者黄河 黄思路）“红厅论坛·比什凯克对话会：中国－中亚国家携手推进落实全球治理倡议”28日在吉尔吉斯斯坦首都比什凯克成功举办，来自中国和中亚五国政府、智库、高校、媒体50余位嘉宾参与对话会。 中央党史和文献研究院第四研究部副主任胡长栓认为，中方提出全球治理倡议，体现了破解世界治理难题的客观需要，反映了国际社会一切爱好和平、向往幸福生活的国家及其人民的共同心声。中国与中亚国家已经建立中国－中亚合作机制，各方应进一步加强文化交流和文明对话，加强经贸领域往来与合作，加强协作共同应对各种危机挑…"
